const AfricasTalking = require('africastalking');

class AfricasTalkingService {
  constructor(credentials) {
    this.client = AfricasTalking({
      apiKey: credentials.apiKey,
      username: credentials.username
    });
    this.sms = this.client.SMS;
    this.voice = this.client.voice;
  }

  async sendSMS(phoneNumber, message, shortCode = null) {
    try {
      const options = {
        to: [phoneNumber],
        message: message,
        from: shortCode || ''
      };

      const response = await this.sms.send(options);
      const result = response.SMSMessageData.Recipients[0];

      return {
        success: result.status === 'Success',
        linkId: result.linkId,
        id: result.messageId,
        statusCode: result.statusCode,
        status: result.status,
        cost: result.messageCost,
        error: result.status !== 'Success' ? result.status : null
      };
    } catch (error) {
      return {
        success: false,
        error: error.message
      };
    }
  }

  async sendIVR(phoneNumber, options) {
    try {
      const callOptions = {
        phoneNumber: phoneNumber,
        callerId: options.callerId || null
      };

      const response = await this.voice.call(callOptions);

      return {
        success: response.status === 'Ok',
        sessionId: response.sessionId,
        status: response.status,
        error: response.status !== 'Ok' ? response.errorMessage : null
      };
    } catch (error) {
      return {
        success: false,
        error: error.message
      };
    }
  }

  async playText(sessionId, ttsText) {
    try {
      const response = await this.voice.playText({ sessionId, text: ttsText });

      return {
        success: true,
        status: response.status
      };
    } catch (error) {
      return {
        success: false,
        error: error.message
      };
    }
  }
}

module.exports = AfricasTalkingService;